def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    for color in counts:
        if color == bg:
            continue
        pts = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == color]

        # A diagonal pair determines the line to extend. Prefer the
        # nearest diagonal pair when a color has extra marks.
        pairs = []
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i + 1:]:
                if abs(r2 - r1) == abs(c2 - c1) and r1 != r2:
                    pairs.append((abs(r2-r1), r1, c1, r2, c2))
        if not pairs:
            continue

        _, r1, c1, r2, c2 = min(pairs)
        dr = 1 if r2 > r1 else -1
        dc = 1 if c2 > c1 else -1

        # Extend the same diagonal from one endpoint in both directions.
        for r, c, sr, sc in ((r1, c1, -dr, -dc), (r2, c2, dr, dc)):
            while 0 <= r < h and 0 <= c < w:
                if out[r][c] not in (bg, color):
                    break
                out[r][c] = color
                r += sr
                c += sc

    return out
